const body = $json.body || $json;

const pain = String(body.pain || '').trim();
const manifestations = String(body.manifestations || '').trim();
const impact = String(body.impact || '').trim();
const desired = String(body.desired || '').trim();
const whyNow = String(body.whyNow || '').trim();
const lifeAfter = String(body.lifeAfter || '').trim();

if (!pain && !manifestations && !impact && !desired && !whyNow && !lifeAfter) {
  throw new Error('Не заполнены данные консультации');
}

const instructions = `Ты помогаешь специалисту анализировать бесплатную консультацию и готовить данные для психологической диагностики. Работай только с тем, что клиент реально сообщил. Не ставь диагнозы. Не придумывай травмы, убеждения, страхи, причины, события или скрытые механизмы, которых нет в данных клиента.

Разделяй две сущности:
1) Развёрнутый основной запрос клиента — цель и задача клиента нормальным человеческим языком. Он может начинаться с «Хочу…» и описывать желаемое изменение.
2) Короткий запрос для Диагностики — текущее препятствие, «камень на дороге», которое мешает прийти к желаемому результату. Это НЕ цель и НЕ желаемый результат.

Правила короткого запроса:
- 3–8 слов, одна ясная мысль;
- не начинай с «Хочу»;
- формулируй текущее препятствие: страх, трудность, избегание, болезненная реакция, невозможность отпустить и т.п. — только если это прямо следует из слов клиента;
- не углубляйся дальше фактов клиента. Если известно только «не получается привлекать клиентов», не выдумывай «страх проявляться»;
- если возможны несколько препятствий, предложи до 4 вариантов и оцени их приоритет в процентах. Самый важный вариант ставь первым. Проценты — это оценка приоритетности по данным консультации, не медицинская вероятность. Сумма процентов должна быть 100;
- если препятствие неясно, не угадывай: дай максимально поверхностную честную формулировку либо не предлагай вариант и задай уточняющий вопрос.

Правила ситуаций:
- извлекай только те ситуации, которые уже названы или однозначно описаны клиентом;
- не придумывай примеры;
- каждая ситуация должна быть конкретным моментом от первого лица в настоящем времени и начинаться с «Когда я…»;
- пример формы: «Когда я пишу потенциальному клиенту», а не «Написать потенциальному клиенту»;
- не ставь уровень дискомфорта — его должен сообщить клиент.

Обоснование должно кратко объяснять, почему первый короткий запрос выглядит наиболее приоритетным, со ссылкой на содержание слов клиента, без выдуманных причин.
Уточняющие вопросы должны помогать точнее определить препятствие или конкретные ситуации. Если уточнение не нужно, верни пустой массив.
Отвечай только валидным JSON без markdown и без текста вокруг JSON.`;

const prompt = `Данные бесплатной консультации:

БОЛЬ КЛИЕНТА:
${pain || 'Не указано'}

ГДЕ ПРОЯВЛЯЕТСЯ:
${manifestations || 'Не указано'}

КАК МЕШАЕТ ЖИТЬ:
${impact || 'Не указано'}

ЧЕГО ХОЧЕТ ВМЕСТО ЭТОГО:
${desired || 'Не указано'}

ПОЧЕМУ ОБРАТИЛСЯ ИМЕННО СЕЙЧАС:
${whyNow || 'Не указано'}

КАК ИЗМЕНИТСЯ ЖИЗНЬ ПОСЛЕ РЕШЕНИЯ ПРОБЛЕМЫ:
${lifeAfter || 'Не указано'}

Верни JSON строго такой структуры:
{
  "mainRequest": "Развёрнутый основной запрос клиента, обычно 1–3 предложения",
  "shortRequests": [
    {"title": "Короткий запрос-препятствие", "priority": 70},
    {"title": "Другой возможный запрос-препятствие", "priority": 30}
  ],
  "rationale": "Почему первый короткий запрос наиболее приоритетен — только по данным клиента",
  "desiredResult": "Что клиент хочет получить и как должна измениться его жизнь после решения проблемы",
  "clarifyingQuestions": ["Уточняющий вопрос 1", "Уточняющий вопрос 2"],
  "situations": ["Когда я ...", "Когда я ..."]
}

Если короткий запрос очевиден, верни один элемент shortRequests с priority 100. Не создавай дополнительные варианты только ради количества.`;

return [{ json: {
  accessKey: String(body.accessKey || ''),
  clientId: String(body.clientId || ''),
  clientName: String(body.clientName || ''),
  instructions,
  prompt
} }];

const r = $json || {};
let text = String(r.output_text || '').trim();

if (!text && Array.isArray(r.output)) {
  for (const item of r.output) {
    if (!Array.isArray(item?.content)) continue;
    for (const part of item.content) {
      if (part?.type === 'output_text' && part?.text) text += String(part.text);
    }
  }
}

text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
if (!text) throw new Error('OpenAI не вернул текст');

let obj;
try {
  obj = JSON.parse(text);
} catch (e) {
  throw new Error('OpenAI вернул невалидный JSON: ' + text.slice(0, 300));
}

const shorts = Array.isArray(obj.shortRequests) ? obj.shortRequests : [];
const normalizedShorts = shorts.map((x, i) => ({
  title: String(x?.title || '').trim(),
  priority: Math.max(0, Math.min(100, Math.round(Number(x?.priority) || (i === 0 ? 100 : 0))))
})).filter(x => x.title).slice(0, 4).sort((a,b) => b.priority - a.priority);

return [{ json: {
  mainRequest: String(obj.mainRequest || '').trim(),
  shortRequests: normalizedShorts,
  rationale: String(obj.rationale || '').trim(),
  desiredResult: String(obj.desiredResult || '').trim(),
  clarifyingQuestions: Array.isArray(obj.clarifyingQuestions) ? obj.clarifyingQuestions.map(x => String(x || '').trim()).filter(Boolean) : [],
  situations: Array.isArray(obj.situations) ? obj.situations.map(x => String(x || '').trim()).filter(Boolean) : []
} }];
